styles.h1:
font-size: 24px;
color: #3a3a3a;
margin-bottom: 15px;
letter-spacing: -0.5px;
font-weight: 600;
text-align: center;
font-family: "Courier New", monospace;
position: relative;
padding-bottom: 10px;

styles.h2:
font-size: 16px;
color: #5a5a5a;
margin-bottom: 24px;
font-weight: 400;
letter-spacing: -0.5px;
text-align: center;
font-style: italic;
font-family: "Courier New", monospace;

styles.h3:
display: block;
color: #3a3a3a;
margin-bottom: 6px;
font-size: 16px;
font-weight: 600;
letter-spacing: -0.5px;
text-decoration: underline;
text-decoration-color: rgba(139, 69, 19, 0.3);
text-underline-offset: 3px;

styles.h6:
color: #6b8c42;
margin-top: 1.2em;
margin-bottom: 0.5em;
font-weight: 700;
border-bottom: 1px solid #d4d9c9;
padding-bottom: 0.3em;

styles.p:
color: #3a3a3a;
font-size: 15px;
position: relative;
font-family: "Courier New", monospace;

styles.a:
color: #8b4513;
text-decoration: none;
border-bottom: 1px dashed #8b4513;
transition: all 0.3s ease;
position: relative;

styles.ol:
list-style: none;
padding: 0.5em 3.5em;
counter-reset: decorated-counter;
margin-bottom: 1.5em;

styles.li:
position: relative;


margin-bottom: 16px;
padding-left: 40px;
color: #3a3a3a;
line-height: 1.6;
font-size: 15px;
font-family: "Courier New", monospace;
letter-spacing: -0.3px;

styles.blockquote:
background: rgba(211, 198, 166, 0.1);
border-left: 3px solid #d3c6a6;
color: #5a5a5a;
padding: 15px 20px;
margin: 20px 0;
font-style: italic;
position: relative;
border-radius: 0 2px 2px 0;

styles.pre:
background: rgba(211, 198, 166, 0.2);
border: 1px solid #d3c6a6;
border-radius: 2px;
padding: 15px;
overflow-x: auto;
position: relative;
font-family: "Courier New", monospace;

styles.hr:
border: 0;
height: 1px;
background: repeating-linear-gradient(
  90deg,
  transparent,
  transparent 5px,
  #d3c6a6 5px,
  #d3c6a6 10px
);
margin: 25px 0;
opacity: 0.7;

styles.img:
max-width: 100%;
border: 1px solid #d3c6a6;
border-radius: 2px;
box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
margin: 20px 0;
padding: 5px;
background: #fff;

styles.table:
width: 100%;
border-collapse: collapse;
margin: 20px 0;
background: rgba(248, 243, 227, 0.5);
border: 1px solid #d3c6a6;

styles.th:
background: rgba(211, 198, 166, 0.2);
color: #3a3a3a;
border-bottom: 1px solid #d3c6a6;
padding: 10px;
font-weight: 600;
text-align: left;
letter-spacing: -0.5px;

styles.td:
color: #3a3a3a;
padding: 10px;
border-bottom: 1px solid rgba(211, 198, 166, 0.5);
letter-spacing: -0.3px;
